files.content:
*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  min-block-size: 100dvb;
  margin: 0;
  padding: 2em;
  font-family: 'Open Sans', sans-serif;
  font-size: 18px;
  background-color: #ffc802;
}

h1,
h2,
h3,
p {
  margin: 0;
}

img {
  inline-size: 100%;
}

ul {
  margin: 0;
  padding: 0;
  list-style: none;
}

.content {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 1em;
}

.friends ul {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
  gap: 1em;
  container-name: cards-list;
  container-type: inline-size;
}

.recommendations {
  grid-column: 1 / -1;
  overflow: hidden;
}

.recommendations ul {
  display: flex;
  gap: 1em;
  padding: 0.5em;
  overflow-x: scroll;
  container-name: cards-list;
  container-type: inline-size;
}

.title {
  margin-block-end: 1em;
  font-size: 2em;
  text-transform: uppercase;
}

.card {
  min-inline-size: 350px;
  border: 1px solid #000;
  background-color: #fff;
  container-name: card;
  container-type: inline-size;
}

@container cards-list (inline-size >= 400px) {
  .card {
    display: grid;
    grid-template-columns: 1fr 1fr;
  }
}

.card__image {
  object-fit: cover;
  object-position: center;
  aspect-ratio: 1 / 1;
}

.card__description {
  display: grid;
  grid-template-rows: min-content min-content 1fr;
  padding: 1em;
}

.card__title {
  margin-block-end: 0.1em;
  font-size: 1.5em;
  text-transform: uppercase;
}

.button {
  display: flex;
  justify-content: center;
  align-items: center;
  inline-size: fit-content;
  block-size: fit-content;
  border: 1px solid #000;
  padding: 0.5em 1em;
  color: #000;
  font-family: inherit;
  font-weight: bold;
  font-size: 1em;
  text-decoration: none;
  text-transform: uppercase;
  background-color: #6dc1fd;
}

.button:hover {
  box-shadow: inset 0 0 0 100px rgb(0 0 0 / 0.15);
  cursor: pointer;
}

.button:focus {
  outline: 2px solid #000;
  outline-offset: 0;
}

.card__profile-link {
  align-self: end;
  margin-top: 1em;
}

@media (width <= 768px) {
  .content {
    grid-template-columns: 1fr;
  }

  .recommendations {
    grid-column: 1;
  }
}
@container card (inline-size <= 400px) {
  .button {
    font-size: clamp(0.8em, 3cqi, 2em);
  }
  .card__description {
    padding: clamp(0.6em, 0.8cqi, 1em);
  }
}
